import {book,movie,routes,timestamp} from './content.js';
import {initial,restore,transition,STORAGE_KEY,stageId} from './model.js';
const root=document.querySelector('#app');
let storageOK=true,state;
try{state=restore(localStorage.getItem(STORAGE_KEY));}catch{state=initial();storageOK=false;}
let resetOpen=false,toolsOpen=false,notice='';
const svg={book:'<path d="M3 5h6a3 3 0 0 1 3 3v13a4 4 0 0 0-4-3H3zm18 0h-6a3 3 0 0 0-3 3v13a4 4 0 0 1 4-3h5z"/>',train:'<rect x="5" y="3" width="14" height="15" rx="4"/><path d="M5 11h14M9 3v8m6-8v8M8 18l-2 3m10-3 2 3M8 15h1m6 0h1"/>',walk:'<circle cx="14" cy="4" r="2"/><path d="m8 21 3-7-2-4 3-3 4 5 4 1M4 12l5-2m2 4 5 3 1 4"/>',play:'<path d="m9 5 10 7-10 7z"/>',pause:'<path d="M9 5v14m6-14v14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',save:'<path d="M6 3h12v18l-6-4-6 4z"/>',check:'<path d="m5 12 4 4L19 6"/>',back:'<path d="m14 6-6 6 6 6"/>',next:'<path d="m10 6 6 6-6 6"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svg[n]||svg.book}</svg>`;
const btn=(a,t,c='',attrs='')=>`<button type="button" data-action="${a}" class="${c}" ${attrs}>${t}</button>`;
const isBook=()=>state.route==='morning';
const title=()=>isBook()?book.title:movie.title;
const position=()=>isBook()?`${state.page}p`:timestamp(state.seconds);
const resumeLabel=()=>isBook()?'이어읽기':'이어보기';
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storageOK=false;}}
function announce(t){document.querySelector('#announcement').textContent=t;}
function dispatch(a){state=transition(state,a);save();render();}
document.querySelector('.brand').addEventListener('click', e => { e.preventDefault(); notice=''; resetOpen=false; dispatch({type:'HOME'}); window.scrollTo(0,0); });
function cover(){return `<div class="book-cover" aria-hidden="true"><span>THE QUIET AFTERNOON</span><div class="cover-window"><i></i><i></i><i></i></div><strong>느린 오후의<br>기록</strong><small>어제의 문장과 오늘의 시간 사이</small></div>`;}
function intro(){return `<section class="intro"><div class="eyebrow">나리가 되어 체험하는 출퇴근길</div><h1>잠깐 멈춰도,<br>내 이야기는 이어지니까.</h1><p class="lead">이동에 집중할 때는 잠시 멈추고,<br>다시 여유가 생기면 그 자리에서 이어가요.</p><div class="route-tabs" role="group" aria-label="시나리오 선택">${btn('morning','출근 · 전자책',isBook()?'selected':'',`aria-pressed="${isBook()}"`)}${btn('evening','퇴근 · 해리포터',!isBook()?'selected':'',`aria-pressed="${!isBook()}"`)}</div>${isBook()?`<div class="intro-question"><span class="eyebrow">오전 8:00 · 출근 시작</span><h2>오늘 출근길에는<br>무엇을 하고 싶나요?</h2></div><article class="choice-card">${cover()}<div><span class="eyebrow">전자책 독서</span><h3>${book.title}</h3><p>${state.page}p · 마지막 읽던 위치</p>${btn('start',`이 책 이어읽기 ${icon('arrow')}`,'primary')}</div></article><div class="reference-activities"><div>${icon('book')}<span>트렌드·뉴스 읽기<small>등록된 활동 · 이번 시나리오에서는 선택하지 않음</small></span></div><div>${icon('play')}<span>해리포터 시리즈 정주행<small>${timestamp(state.seconds)} · 퇴근 시나리오에서 체험</small></span></div></div>`:`<div class="notification-time">18:30<span>퇴근 시작 전</span></div><article class="notification"><div class="notification-label"><span class="mini-brand">↗</span> 이어봄 <small>지금</small></div><h2>퇴근할 시간이에요.</h2><p>이 시간에는 주로 해리포터 정주행을 했어요. 계속해볼까요?</p><div class="saved-line">${icon('save')} ${timestamp(state.seconds)} · 지난번 멈춘 곳</div>${btn('start',`알림 열고 이어가기 ${icon('arrow')}`,'primary full')}</article><p class="caption center">잠금화면 알림을 웹 안에서 재현한 화면입니다.</p>`}<div class="route-preview">${icon('train')}<div><strong>${isBook()?'집 → 회사':'회사 → 집'}</strong><span>도보 · 지하철 · 환승 · 지하철 · 도보</span></div><span class="pill">가상 이동</span></div><p class="caption center">아래 ‘다음 상황’ 버튼으로 이동 시간을 건너뛸 수 있어요.</p></section>`;}
function transit(){const stage=routes[state.route].stages[state.stage];return `<section class="transit"><div class="transit-top"><span class="eyebrow">오늘의 ${routes[state.route].label}길</span><span class="simulation-badge">가상 이동</span></div><div class="transit-main"><div class="transit-icon">${icon(['walk','transfer','arrival'].includes(stage[0])?'walk':'train')}</div><div><h1>${stage[1]}</h1><p>${stage[3]}</p></div><strong class="trip-time">${stage[2]}</strong></div><div class="route-dots">${routes[state.route].stages.map((_,i)=>`<span class="${i<=state.stage?'passed':''} ${i===state.stage?'current':''}"></span>`).join('')}</div></section>`;}
function savedCard(){return `<div class="saved-content"><div class="mini-cover">${icon(isBook()?'book':'play')}</div><div><span>${isBook()?'전자책 독서':'영상 시청'}</span><strong>${title()}</strong><small>${position()} · 마지막 위치 ${storageOK?'저장됨':'유지 중'}</small></div></div>`;}
function waiting(){const id=stageId(state);const walk=id==='walk';return `<section class="rest-screen"><div class="rest-illustration">${icon('walk')}<span></span><span></span></div><span class="eyebrow">${walk?'시작 준비':'잠시 중단'}</span><h2>${walk?'지금은 이동에<br>집중해도 괜찮아요.':'독서가 끝난 게 아니라,<br>잠깐 멈춘 거예요.'.replace('독서',isBook()?'독서':'이야기')}</h2><p>${walk?'무엇을 할지 다시 고민하지 않도록<br>선택한 활동을 준비해둘게요.':'방금까지 보던 위치를 기억해뒀어요.<br>다음 승강장에서 편하게 이어가세요.'}</p>${savedCard()}<div class="quiet-line">${icon('check')} ${walk?'선택한 활동을 유지하고 있어요':'직접 저장하지 않아도 위치를 기억해요'}</div></section>`;}
function returnPoint(){return `<section class="return-screen"><div class="return-label">RETURN POINT <span>다시 이어갈 순간</span></div><h2>${isBook()?'아까 읽던 책,<br>이어갈까요?':'잠깐 멈췄던 이야기,<br>이어볼까요?'}</h2><p>찾을 필요 없이, 멈췄던 그 자리에서.</p>${savedCard()}<div class="return-position"><span>저장된 ${isBook()?'페이지':'시청 위치'}</span><strong data-testid="return-position">${position()}</strong></div>${btn('resume',`${icon(isBook()?'book':'play')} ${position()}부터 ${resumeLabel()}`,'primary full')}${btn('later','탑승 후 이어갈게요','text-button full')}</section>`;}
function social(){if(state.social==='returned')return player();if(state.social==='message')return `<section class="social-screen"><span class="eyebrow">승강장에서 잠깐</span><h2>동료에게 온 메시지를<br>확인했어요.</h2><div class="message-bubble"><span>회사 동료 · 메시지 예시</span><p>오늘도 고생했어요! 내일 봐요 🙂</p></div><p class="lead">열차를 기다리다가<br>습관적으로 SNS를 열게 됩니다.</p>${btn('feed','SNS를 열어보기','secondary full')}<p class="caption">시나리오의 이탈 상황을 재현하는 모의 화면입니다.</p></section>`;return `<section class="social-screen"><div class="feed-label">SNS 피드를 보는 중 <span>모의 화면</span></div><div class="feed-placeholder"><div class="feed-avatar"></div><div class="feed-landscape"><span>일상의 순간들</span></div><div class="feed-lines"><i></i><i></i></div></div>${state.social==='feed'?btn('reminder','잠시 후 · 복귀 알림 받기','secondary full'):`<article class="notification return-notification"><div class="notification-label"><span class="mini-brand">↗</span> 이어봄 <small>지금</small></div><h2>호그와트로 돌아갈<br>준비됐나요?</h2><p>지난 이야기 ${timestamp(state.seconds)}에서 기다리고 있어요.</p>${btn('resume',`${timestamp(state.seconds)}부터 이어보기`,'primary full')}${btn('dismiss','지금은 괜찮아요','text-button full')}</article>`}</section>`;}
function player(){const near=stageId(state)==='near';return `${near?`<aside class="quiet-notice">${icon('save')}<div><strong>환승까지 약 2분</strong><span>내릴 곳이 가까워졌어요.</span></div>${btn('pause','여기까지 저장','text-button')}</aside>`:''}<section class="activity"><div class="activity-heading"><span class="eyebrow">${isBook()?'전자책 독서':'영상 시청'}</span><span class="saved-badge">${icon('check')} ${storageOK?'위치 저장됨':'위치 유지 중'}</span></div><h2 class="article-title">${title()}</h2><div class="meta">${isBook()?book.author:'OTT 연결 모의 화면 · 실제 영화·음성 없음'}</div>${isBook()?reader():video()}${state.paused?`<div class="paused-bar"><span>${position()}에서 잠시 멈췄어요.</span>${btn('resume',resumeLabel(),'primary')}</div>`:btn('pause',`${icon('pause')} 잠시 멈추기`,'secondary full')}<p class="caption center">${isBook()?'현재 페이지가 자동으로 저장됩니다.':'모의 재생 시간이 흐르며 현재 위치가 저장됩니다.'}</p></section>`;}
function reader(){const p=book.pages[state.page-book.firstPage];return `<article class="reading ${state.paused?'paused-reading':''}"><div class="book-chapter">CHAPTER 07 <span>다시 이어지는 시간</span></div><h3>${p[0]}</h3><p class="body-text">${p[1]}</p><div class="page-controls">${btn('previous',icon('back'),'icon-button',`aria-label="이전 페이지" ${state.paused||state.page===132?'disabled':''}`)}<span><strong data-testid="page-position">${state.page}</strong> p</span>${btn('next',icon('next'),'icon-button',`aria-label="다음 페이지" ${state.paused||state.page===151?'disabled':''}`)}</div></article>`;}
function video(){return `<div class="movie-stage ${state.paused?'':'playing'}"><div class="night-sky"><i></i><i></i><i></i><div class="moon"></div><div class="castle">♜</div></div><div class="movie-label">HARRY POTTER<span>시청 경험 시뮬레이션</span></div><span class="play-state">${icon(state.paused?'pause':'play')} ${state.paused?'일시정지':'모의 재생 중'}</span></div><div class="video-timeline"><progress max="${movie.duration}" value="${state.seconds}" aria-label="시청 진행 위치"></progress><div><strong data-testid="video-position">${timestamp(state.seconds)}</strong><span>${timestamp(movie.duration)}</span></div></div>`;}
function session(){const id=stageId(state);let body='';if(['walk','transfer'].includes(id))body=waiting();else if(id==='wait'&&!isBook())body=social();else if(id==='return'&&state.paused)body=returnPoint();else if(id==='wait'&&state.paused)body=`<section class="platform-screen"><span class="eyebrow">시작은 가볍게</span><h2>열차까지 약 3분.<br>잠깐 먼저 읽어볼까요?</h2><p>혼잡하거나 곧 열차가 온다면<br>탑승 후 시작해도 좋아요.</p>${savedCard()}${btn('resume','2분 먼저 읽기','primary full')}${btn('wait','탑승 후 이어읽기','secondary full')}</section>`;else body=player();return transit()+body+simulator();}
function simulator(){const stage=routes[state.route].stages;return `<section class="simulator"><div class="sim-head"><span><i></i> 테스트용 상황 제어</span><span>${state.stage+1} / 8</span></div>${btn('advance',`다음 상황 · ${stage[Math.min(state.stage+1,7)][1]} ${icon('arrow')}`,'simulate-next full')}<details id="tools" ${toolsOpen?'open':''}><summary>테스트 도구</summary><p class="caption">표시된 구간 시간은 시나리오의 가상 시간입니다. 실제로 기다릴 필요는 없어요.</p>${!isBook()&&!state.paused?btn('skip-video','시청 시간 19분 진행 (테스트용)','secondary full'):''}<div class="tool-row">${btn('end','여기서 활동 종료','text-button')}${btn('reset','테스트 초기화','text-button')}</div></details>${resetOpen?resetPanel():''}</section>`;}
function resetPanel(){return `<div class="reset-panel"><p>저장된 페이지·시청 위치를 지우고 처음부터 체험할까요?</p><div class="choice-row">${btn('cancel-reset','취소','secondary')}${btn('confirm-reset','초기화하기','primary')}</div></div>`;}
function summary(){const diff=state.seconds-state.startSeconds;return `${transit()}<section class="summary"><div class="summary-mark">${icon('check')}</div><span class="eyebrow">오늘의 ${routes[state.route].label}길</span><h1>잠시 멈췄던 이야기,<br>다시 이어온 시간.</h1><p class="lead">남은 이야기는 다음 이동에서 만나요.</p><div class="summary-card"><span class="eyebrow">${isBook()?'이번에 읽은 위치':'이번 시청 위치'}</span><h2>${title()}</h2><div class="position-range">${isBook()?`${state.startPage}p → ${state.page}p`:`${timestamp(state.startSeconds)} → ${timestamp(state.seconds)}`}</div><p>${isBook()?'직접 넘긴 페이지를 기준으로 기록했어요.':`모의 시청 ${Math.floor(diff/60)}분 ${Math.floor(diff%60)}초 · 테스트로 넘긴 시간 포함`}</p><div class="summary-return">${icon('save')} 다음에도 ${position()}부터 이어갈 수 있어요.</div></div><p class="caption">${isBook()?'이번 체험에서 이동한 페이지를 기록했어요.':'모의 시청 기록이며 실제 영상 재생시간은 아닙니다.'}</p>${btn('start',`다음 이동에서 ${resumeLabel()} ${icon('arrow')}`,'primary full summary-next')}<div class="summary-actions">${btn(isBook()?'evening':'morning',isBook()?'퇴근 시나리오 체험':'출근 시나리오 체험','secondary full')}${btn('reset','테스트 초기화','text-button full')}</div>${resetOpen?resetPanel():''}</section>`;}
function render(){const action=document.activeElement?.dataset?.action;root.innerHTML=`${!storageOK?'<p class="storage-warning">저장을 사용할 수 없어 새로고침 시 위치가 사라질 수 있어요.</p>':''}${notice?`<div class="toast" role="status">${notice}</div>`:''}${state.screen==='intro'?intro():state.screen==='summary'?summary():session()}`;root.querySelector('#tools')?.addEventListener('toggle',e=>toolsOpen=e.target.open);if(action)root.querySelector(`[data-action="${action}"]`)?.focus({preventScroll:true});}
root.addEventListener('click',e=>{const b=e.target.closest('button[data-action]');if(!b)return;const a=b.dataset.action;notice='';if(a==='reset'||a==='cancel-reset'){resetOpen=a==='reset';render();return;}if(a==='confirm-reset'){resetOpen=false;toolsOpen=false;dispatch({type:'RESET'});window.scrollTo(0,0);return;}if(a==='morning'||a==='evening'){dispatch({type:'ROUTE',route:a});window.scrollTo(0,0);return;}if(a==='start'){dispatch({type:'START'});window.scrollTo(0,0);return;}if(a==='advance'){dispatch({type:'ADVANCE'});window.scrollTo(0,0);announce(`${routes[state.route].stages[state.stage][1]}. ${state.paused?'이전 위치가 저장되어 있어요.':''}`);return;}if(a==='next'||a==='previous'){dispatch({type:'PAGE',delta:a==='next'?1:-1});announce(`${state.page}페이지`);return;}if(a==='feed'||a==='reminder'){dispatch({type:'SOCIAL',value:a});return;}if(a==='dismiss'){dispatch({type:'SOCIAL',value:'feed'});return;}if(a==='wait'||a==='later'){notice='탑승 후에도 저장한 위치에서 이어갈 수 있어요.';dispatch({type:'PAUSE'});return;}if(a==='skip-video'){dispatch({type:'TICK',seconds:19*60});return;}if(a==='resume'){dispatch({type:'RESUME'});announce(`${position()}부터 ${resumeLabel()}를 시작했어요.`);return;}dispatch({type:a.toUpperCase()});if(a==='end')window.scrollTo(0,0);});
let lastTick=Date.now();setInterval(()=>{const now=Date.now(),elapsed=Math.floor((now-lastTick)/1000);if(elapsed<1)return;lastTick=now;if(state.route==='evening'&&!state.paused&&state.screen==='session'){state=transition(state,{type:'TICK',seconds:Math.min(elapsed,2)});save();const label=root.querySelector('[data-testid="video-position"]');if(label)label.textContent=timestamp(state.seconds);const progress=root.querySelector('.video-timeline progress');if(progress)progress.value=state.seconds;if(state.paused)render();}},1000);
function suspend(){if(!state.paused){state=transition(state,{type:'PAUSE'});save();render();}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend();});window.addEventListener('pagehide',()=>{suspend();save();});render();
